const listDocumentEmbedHashes = `-- name: ListDocumentEmbedHashes :many
SELECT DISTINCT c.embed_hash FROM knowledge_document_chunks c
WHERE c.workspace_id = $1 AND c.document_id = $2
  AND NOT EXISTS (
      SELECT 1 FROM knowledge_embeddings e
      WHERE e.workspace_id = $1 AND e.model_key = $3 AND e.embed_hash = c.embed_hash
  )
ORDER BY 1
`

type ListDocumentEmbedHashesParams struct {
	WorkspaceID ids.UUID `json:"workspace_id"`
	DocumentID  ids.UUID `json:"document_id"`
	ModelKey    string   `json:"model_key"`
}

// ListDocumentEmbedHashes lists the hashes of a document's chunks with
// no vector of the model.
func (q *Queries) ListDocumentEmbedHashes(ctx context.Context, arg ListDocumentEmbedHashesParams) ([]string, error) {
	rows, err := q.db.Query(ctx, listDocumentEmbedHashes, arg.WorkspaceID, arg.DocumentID, arg.ModelKey)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var embed_hash string
		if err := rows.Scan(&embed_hash); err != nil {
			return nil, err
		}
		items = append(items, embed_hash)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

