const removeUnseenKnowledgeDocuments = `-- name: RemoveUnseenKnowledgeDocuments :many
UPDATE knowledge_documents
SET status = 'removed', updated_at = $1
WHERE workspace_id = $2 AND source_id = $3 AND status IN ('pending', 'active', 'error')
  AND (last_seen_run_id IS NULL OR last_seen_run_id <> $4)
RETURNING id
`

type RemoveUnseenKnowledgeDocumentsParams struct {
	Now         time.Time `json:"now"`
	WorkspaceID ids.UUID  `json:"workspace_id"`
	SourceID    ids.UUID  `json:"source_id"`
	RunID       *ids.UUID `json:"run_id"`
}

// RemoveUnseenKnowledgeDocuments drops the documents a complete run no
// longer saw, members' exclusions aside, and returns them.
func (q *Queries) RemoveUnseenKnowledgeDocuments(ctx context.Context, arg RemoveUnseenKnowledgeDocumentsParams) ([]ids.UUID, error) {
	rows, err := q.db.Query(ctx, removeUnseenKnowledgeDocuments,
		arg.Now,
		arg.WorkspaceID,
		arg.SourceID,
		arg.RunID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ids.UUID
	for rows.Next() {
		var id ids.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchKnowledgeDocumentChunksVector = `-- name: SearchKnowledgeDocumentChunksVector :many
SELECT c.id, c.document_id, c.source_id, s.type AS source_type, c.title, c.heading_path, c.body, c.visibility,
    d.url, d.locale, d.indexed_at, (e.embedding <=> $1::halfvec)::float8 AS distance
FROM knowledge_document_chunks c
JOIN knowledge_documents d ON d.id = c.document_id
JOIN knowledge_sources s ON s.id = c.source_id
JOIN knowledge_embeddings e
    ON e.workspace_id = c.workspace_id AND e.model_key = $2 AND e.embed_hash = c.embed_hash
WHERE c.workspace_id = $3 AND d.status = 'active' AND s.mode = 'sync' AND $4::text = ANY (s.targets)
  AND c.visibility = ANY ($5::text[])
  AND (cardinality($6::text[]) = 0 OR c.embed_hash = ANY ($6::text[]))
ORDER BY distance, c.id
LIMIT $7
`

type SearchKnowledgeDocumentChunksVectorParams struct {
	Embedding    database.HalfVector `json:"embedding"`
	ModelKey     string              `json:"model_key"`
	WorkspaceID  ids.UUID            `json:"workspace_id"`
	Target       string              `json:"target"`
	Visibilities []string            `json:"visibilities"`
	Hashes       []string            `json:"hashes"`
	RowLimit     int32               `json:"row_limit"`
}

type SearchKnowledgeDocumentChunksVectorRow struct {
	ID          ids.UUID   `json:"id"`
	DocumentID  ids.UUID   `json:"document_id"`
	SourceID    ids.UUID   `json:"source_id"`
	SourceType  string     `json:"source_type"`
	Title       string     `json:"title"`
	HeadingPath []string   `json:"heading_path"`
	Body        string     `json:"body"`
	Visibility  string     `json:"visibility"`
	Url         *string    `json:"url"`
	Locale      string     `json:"locale"`
	IndexedAt   *time.Time `json:"indexed_at"`
	Distance    float64    `json:"distance"`
}

// SearchKnowledgeDocumentChunksVector ranks the live chunks of sources
// feeding the target by cosine distance to the query vector.
func (q *Queries) SearchKnowledgeDocumentChunksVector(ctx context.Context, arg SearchKnowledgeDocumentChunksVectorParams) ([]SearchKnowledgeDocumentChunksVectorRow, error) {
	rows, err := q.db.Query(ctx, searchKnowledgeDocumentChunksVector,
		arg.Embedding,
		arg.ModelKey,
		arg.WorkspaceID,
		arg.Target,
		arg.Visibilities,
		arg.Hashes,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchKnowledgeDocumentChunksVectorRow
	for rows.Next() {
		var i SearchKnowledgeDocumentChunksVectorRow
		if err := rows.Scan(
			&i.ID,
			&i.DocumentID,
			&i.SourceID,
			&i.SourceType,
			&i.Title,
			&i.HeadingPath,
			&i.Body,
			&i.Visibility,
			&i.Url,
			&i.Locale,
			&i.IndexedAt,
			&i.Distance,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

